'use client'

/**
 * SUPER ARCHIVE BROS. — a complete Mario-style side-scrolling platformer,
 * built from scratch for the archive. No ROMs, no emulators, no external
 * assets: every sprite is drawn with canvas rects, every sound is
 * synthesized with WebAudio, the three courses are generated by a small
 * level builder, and the engine (fixed-timestep physics, tile collision,
 * stomp/power-up/flag sequences) lives entirely in this file.
 *
 * Controls: ← → move · Z / Space jump (hold = higher) · X / Shift run
 *           Enter start / pause · M sound. Touch pads on mobile.
 */

import { useEffect, useRef, useState } from 'react'

/* ============================== CONSTANTS ============================== */

const TILE = 16
const VW = 256   // logical viewport width  (16 tiles)
const VH = 240   // logical viewport height (15 tiles)
const ROWS = 15
const SCALE = 3  // canvas backing scale (768×720)
const STEP = 1000 / 60

/* ============================== TYPES ============================== */

type Theme = 'day' | 'dusk' | 'night'

type Level = {
  w: number
  grid: string[][]            // [row][col]
  spawns: { tx: number; ty: number }[]
  flagX: number
  name: string
  theme: Theme
  clouds: { x: number; y: number }[]
  hills: number[]
  stars: { x: number; y: number }[]
}

type Box = { x: number; y: number; w: number; h: number; vx: number; vy: number }

type Player = Box & {
  face: 1 | -1
  onG: boolean
  coyote: number
  buf: number
  anim: number
  inv: number
  big: boolean
}

type Enemy = Box & { dir: 1 | -1; squish: number }

type Item = Box & { rise: number; dir: 1 | -1 }
type Pop = { x: number; y: number; vy: number; t: number }
type Part = { x: number; y: number; vx: number; vy: number; t: number }
type Bump = { cx: number; cy: number; t: number }

type State =
  | 'title' | 'intro' | 'playing' | 'pause' | 'dying'
  | 'flag' | 'walkoff' | 'clear' | 'gameover' | 'win'

/* ============================== AUDIO ============================== */

let AC: AudioContext | null = null
let master: GainNode | null = null

function ensureAudio() {
  if (AC) { if (AC.state === 'suspended') void AC.resume(); return }
  try {
    const Ctor = window.AudioContext
      ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext
    if (!Ctor) return
    AC = new Ctor()
    master = AC.createGain()
    master.gain.value = 0.5
    master.connect(AC.destination)
  } catch { AC = null }
}

function tone(f0: number, f1: number, dur: number, type: OscillatorType, vol: number, delay = 0) {
  if (!AC || !master || muted()) return
  const t = AC.currentTime + delay
  const o = AC.createOscillator()
  const g = AC.createGain()
  o.type = type
  o.frequency.setValueAtTime(Math.max(20, f0), t)
  if (f1 !== f0) o.frequency.exponentialRampToValueAtTime(Math.max(20, f1), t + dur)
  g.gain.setValueAtTime(vol, t)
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur)
  o.connect(g); g.connect(master)
  o.start(t); o.stop(t + dur + 0.02)
}

function noiseBurst(dur: number, vol: number) {
  if (!AC || !master || muted()) return
  const n = Math.floor(AC.sampleRate * dur)
  const buf = AC.createBuffer(1, n, AC.sampleRate)
  const d = buf.getChannelData(0)
  for (let i = 0; i < n; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / n)
  const src = AC.createBufferSource()
  const g = AC.createGain()
  src.buffer = buf
  g.gain.value = vol
  src.connect(g); g.connect(master)
  src.start()
}

let mutedFlag = false
function muted() { return mutedFlag }

type Sfx =
  | 'jump' | 'coin' | 'stomp' | 'bump' | 'break' | 'power' | 'shrink'
  | 'oneup' | 'die' | 'flag' | 'pause' | 'note' | 'bass'

function midi(n: number): number { return 440 * Math.pow(2, (n - 69) / 12) }

function sfx(name: Sfx) {
  if (!AC) return
  switch (name) {
    case 'jump': tone(240, 620, 0.14, 'square', 0.10); break
    case 'coin': tone(988, 988, 0.06, 'square', 0.10); tone(1319, 1319, 0.12, 'square', 0.10, 0.06); break
    case 'stomp': tone(320, 70, 0.10, 'square', 0.12); break
    case 'bump': tone(140, 90, 0.07, 'square', 0.10); break
    case 'break': noiseBurst(0.16, 0.14); break
    case 'power': [392, 523, 659, 784, 988].forEach((f, i) => tone(f, f, 0.07, 'square', 0.09, i * 0.055)); break
    case 'shrink': [700, 500, 340, 220].forEach((f, i) => tone(f, f, 0.07, 'square', 0.09, i * 0.055)); break
    case 'oneup': [660, 784, 988, 1319].forEach((f, i) => tone(f, f, 0.08, 'square', 0.09, i * 0.07)); break
    case 'die': [600, 500, 400, 300, 200, 120].forEach((f, i) => tone(f, f * 0.9, 0.09, 'square', 0.11, i * 0.08)); break
    case 'flag': [523, 587, 659, 698, 784, 880, 988].forEach((f, i) => tone(f, f, 0.07, 'square', 0.08, i * 0.06)); break
    case 'pause': tone(880, 880, 0.05, 'square', 0.08); tone(660, 660, 0.05, 'square', 0.08, 0.08); break
    case 'note': break // handled by sequencer directly
    case 'bass': break
  }
}

