/* ============================== LEVELS ============================== */

function makeLevel(w: number, theme: Theme, name: string): Level {
  const grid: string[][] = Array.from({ length: ROWS }, () => Array<string>(w).fill('.'))
  return { w, grid, spawns: [], flagX: w - 12, name, theme, clouds: [], hills: [], stars: [] }
}

function ground(l: Level, x0: number, x1: number) {
  for (let x = x0; x <= x1; x++) {
    if (x < 0 || x >= l.w) continue
    l.grid[13][x] = '#'
    l.grid[14][x] = '#'
  }
}
function gap(l: Level, x0: number, x1: number) {
  for (let x = x0; x <= x1; x++) { l.grid[13][x] = '.'; l.grid[14][x] = '.' }
}
function put(l: Level, x: number, y: number, ch: string) {
  if (x >= 0 && x < l.w && y >= 0 && y < ROWS) l.grid[y][x] = ch
}
function row(l: Level, x0: number, x1: number, y: number, ch: string) {
  for (let x = x0; x <= x1; x++) put(l, x, y, ch)
}
function coins(l: Level, x0: number, x1: number, y: number) { row(l, x0, x1, y, 'o') }
function pipe(l: Level, x: number, h: number) {
  const lip = 13 - h
  put(l, x, lip, 'p'); put(l, x + 1, lip, 'p')
  for (let y = lip + 1; y <= 12; y++) { put(l, x, y, 'I'); put(l, x + 1, y, 'I') }
}
function stairs(l: Level, x: number, h: number, dir: 1 | -1) {
  for (let i = 0; i < h; i++) {
    const col = dir === 1 ? x + i : x + i
    const height = dir === 1 ? i + 1 : h - i
    for (let y = 12; y > 12 - height; y--) put(l, col, y, 'X')
  }
}
function goomba(l: Level, tx: number, ty = 12) { l.spawns.push({ tx, ty }) }
function flagAt(l: Level, x: number) {
  l.flagX = x
  put(l, x, 2, 'T')
  for (let y = 3; y <= 12; y++) put(l, x, y, 'F')
}

function decorate(l: Level) {
  // deterministic seeded decoration
  let s = l.w * 7 + l.name.length * 13
  const rnd = () => { s = (s * 1103515245 + 12345) & 0x7fffffff; return s / 0x7fffffff }
  for (let x = 24; x < l.w * 16 - 60; x += 66 + Math.floor(rnd() * 50)) {
    l.clouds.push({ x, y: 20 + Math.floor(rnd() * 40) })
  }
  for (let x = 8; x < l.w; x += 14 + Math.floor(rnd() * 22)) {
    if (l.grid[13][x] === '#') l.hills.push(x)
  }
  if (l.theme === 'night' || l.theme === 'dusk') {
    for (let i = 0; i < 60; i++) l.stars.push({ x: Math.floor(rnd() * l.w * 16), y: Math.floor(rnd() * 150) })
  }
}

function build(index: number): Level {
  if (index === 0) {
    const l = makeLevel(212, 'day', '1-1')
    ground(l, 0, 211)
    gap(l, 69, 70); gap(l, 86, 88); gap(l, 153, 154)
    put(l, 16, 9, 'Q')
    row(l, 20, 24, 9, 'B'); put(l, 21, 9, 'Q'); put(l, 23, 9, 'M')
    put(l, 22, 5, 'Q')
    pipe(l, 28, 2); pipe(l, 38, 3); pipe(l, 46, 4); pipe(l, 56, 4)
    goomba(l, 41); goomba(l, 51); goomba(l, 53); goomba(l, 63)
    row(l, 77, 79, 9, 'B'); put(l, 78, 9, 'Q')
    goomba(l, 81)
    coins(l, 86, 88, 8)
    row(l, 91, 95, 9, 'B'); coins(l, 91, 95, 8)
    goomba(l, 97); goomba(l, 99)
    put(l, 100, 5, 'B'); put(l, 101, 5, 'Q')
    row(l, 106, 108, 9, 'B'); put(l, 107, 9, 'Q')
    goomba(l, 110); goomba(l, 112); goomba(l, 114)
    stairs(l, 118, 4, 1); stairs(l, 123, 4, -1)
    goomba(l, 131); goomba(l, 133)
    pipe(l, 140, 2); goomba(l, 144); pipe(l, 148, 2)
    row(l, 160, 162, 9, 'B'); put(l, 161, 9, 'Q')
    goomba(l, 165); goomba(l, 167); goomba(l, 169)
    coins(l, 172, 175, 9)
    stairs(l, 179, 8, 1)
    flagAt(l, 193)
    decorate(l)
    return l
  }
  if (index === 1) {
    const l = makeLevel(200, 'dusk', '2-1')
    ground(l, 0, 199)
    gap(l, 40, 42); gap(l, 75, 77); gap(l, 118, 121); gap(l, 150, 153)
    pipe(l, 20, 3); pipe(l, 30, 4)
    goomba(l, 25); goomba(l, 35)
    coins(l, 40, 42, 8)
    row(l, 48, 52, 8, 'B'); coins(l, 48, 52, 7); goomba(l, 50, 7)
    put(l, 56, 9, 'Q'); put(l, 58, 9, 'M')
    goomba(l, 62); goomba(l, 64)
    row(l, 68, 72, 9, 'B'); put(l, 70, 9, 'Q')
    coins(l, 75, 77, 8)
    pipe(l, 84, 5); goomba(l, 90); goomba(l, 92); pipe(l, 94, 3)
    row(l, 100, 104, 8, 'B'); put(l, 102, 8, 'Q'); coins(l, 100, 104, 7)
    goomba(l, 108); goomba(l, 110)
    stairs(l, 114, 3, 1)
    coins(l, 118, 121, 7)
    row(l, 128, 132, 9, 'B'); put(l, 130, 9, 'Q')
    goomba(l, 135); goomba(l, 137); goomba(l, 139)
    pipe(l, 144, 4)
    coins(l, 150, 153, 8)
    row(l, 158, 161, 9, 'B'); put(l, 159, 9, 'Q'); put(l, 160, 9, 'Q')
    goomba(l, 166); goomba(l, 168)
    stairs(l, 172, 5, 1); stairs(l, 179, 5, -1)
    goomba(l, 186)
    flagAt(l, 192)
    decorate(l)
    return l
  }
  const l = makeLevel(210, 'night', '3-1')
  ground(l, 0, 209)
  gap(l, 30, 33); gap(l, 50, 54); gap(l, 72, 80); gap(l, 100, 104)
  gap(l, 128, 133); gap(l, 158, 162)
  put(l, 20, 9, 'Q'); put(l, 22, 9, 'M')
  goomba(l, 26)
  coins(l, 30, 33, 8)
  row(l, 38, 42, 9, 'B'); goomba(l, 40, 8); coins(l, 38, 42, 8)
  pipe(l, 46, 2)
  coins(l, 50, 54, 8)
  row(l, 58, 62, 9, 'B'); put(l, 60, 9, 'Q')
  goomba(l, 66); goomba(l, 68)
  row(l, 72, 80, 6, 'B'); put(l, 76, 6, 'Q'); coins(l, 73, 79, 5)
  goomba(l, 74, 5); goomba(l, 78, 5)
  goomba(l, 85); goomba(l, 87); goomba(l, 89)
  stairs(l, 94, 4, 1)
  coins(l, 100, 104, 7)
  row(l, 108, 112, 9, 'B'); put(l, 110, 9, 'Q')
  goomba(l, 116); goomba(l, 118)
  pipe(l, 122, 3)
  row(l, 128, 133, 8, 'B'); coins(l, 129, 132, 7); goomba(l, 130, 7)
  goomba(l, 138); goomba(l, 140); goomba(l, 142); goomba(l, 144)
  row(l, 148, 152, 9, 'B'); put(l, 150, 9, 'Q')
  coins(l, 158, 162, 8)
  stairs(l, 168, 6, 1)
  row(l, 178, 182, 5, 'B'); put(l, 180, 5, 'Q')
  goomba(l, 186); goomba(l, 188); goomba(l, 190)
  stairs(l, 192, 6, 1)
  flagAt(l, 203)
  decorate(l)
  return l
}

const LEVEL_COUNT = 3

/* ============================== SPRITES ============================== */

const C = {
  red: '#e23b2e', skin: '#f8b878', blue: '#2b58c8', boot: '#7a4a1e',
  dark: '#101010', gBody: '#a05a20', gDark: '#5c3410', gFoot: '#e8c088',
  gold: '#f8b800', goldIn: '#c87800', brick: '#9c4a00', brickHi: '#e8883c',
  q: '#f0a020', qDark: '#7a4a00', stone: '#c0b8a0', stoneHi: '#e8e0c8',
  stoneLo: '#6a6458', pipe: '#30a020', pipeHi: '#78d048', pipeLo: '#0a5a0a',
  ground: '#9c4a00', groundHi: '#e8883c', groundLo: '#5c2800',
  white: '#f8f8f8', pole: '#d8d8d8',
}

function px(c: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, color: string) {
  c.fillStyle = color
  c.fillRect(Math.round(x), Math.round(y), w, h)
}

function drawHero(c: CanvasRenderingContext2D, x: number, y: number, big: boolean, face: 1 | -1, pose: 'stand' | 'walk1' | 'walk2' | 'jump') {
  const w = 12
  c.save()
  c.translate(Math.round(x) + w / 2, Math.round(y))
  c.scale(face, 1)
  c.translate(-w / 2, 0)
  if (big) {
    // cap
    px(c, 2, 0, 8, 3, C.red); px(c, 0, 3, 11, 2, C.red)
    // face
    px(c, 2, 5, 8, 6, C.skin); px(c, 1, 5, 1, 3, C.boot) // sideburn
    px(c, 7, 6, 2, 2, C.dark)                            // eye
    px(c, 4, 9, 6, 2, C.dark)                            // mustache
    // shirt + arms
    px(c, 1, 11, 10, 5, C.red)
    if (pose === 'jump') { px(c, 0, 8, 2, 4, C.skin); px(c, 10, 8, 2, 4, C.skin) }
    else { px(c, 0, 12, 2, 4, C.skin); px(c, 10, 12, 2, 4, C.skin) }
    // overalls
    px(c, 2, 14, 8, 7, C.blue)
    px(c, 3, 14, 1, 1, C.gold); px(c, 8, 14, 1, 1, C.gold)
    px(c, 4, 16, 4, 5, C.blue)
    // legs + boots
    if (pose === 'walk1') { px(c, 1, 21, 4, 4, C.blue); px(c, 7, 21, 4, 4, C.blue); px(c, 0, 25, 5, 3, C.boot); px(c, 7, 25, 5, 3, C.boot) }
    else if (pose === 'walk2') { px(c, 3, 21, 6, 4, C.blue); px(c, 2, 25, 4, 3, C.boot); px(c, 7, 25, 4, 3, C.boot) }
    else if (pose === 'jump') { px(c, 2, 20, 3, 5, C.blue); px(c, 7, 21, 3, 4, C.blue); px(c, 1, 24, 4, 3, C.boot); px(c, 7, 24, 4, 3, C.boot) }
    else { px(c, 2, 21, 3, 4, C.blue); px(c, 7, 21, 3, 4, C.blue); px(c, 1, 25, 4, 3, C.boot); px(c, 7, 25, 4, 3, C.boot) }
  } else {
    px(c, 2, 0, 8, 2, C.red); px(c, 1, 2, 10, 2, C.red)   // cap
    px(c, 2, 4, 8, 4, C.skin); px(c, 1, 4, 1, 2, C.boot)  // face + sideburn
    px(c, 7, 5, 2, 2, C.dark)                             // eye
    px(c, 4, 7, 5, 1, C.dark)                             // mustache
    px(c, 2, 8, 8, 3, C.red)                              // shirt
    if (pose === 'jump') { px(c, 0, 6, 2, 3, C.skin); px(c, 10, 6, 2, 3, C.skin) }
    else { px(c, 1, 9, 2, 3, C.skin); px(c, 9, 9, 2, 3, C.skin) }
    px(c, 2, 10, 8, 4, C.blue)                            // overalls
    px(c, 3, 10, 1, 1, C.gold); px(c, 8, 10, 1, 1, C.gold)
    if (pose === 'walk1') { px(c, 1, 13, 4, 2, C.blue); px(c, 7, 13, 4, 2, C.blue); px(c, 0, 14, 5, 2, C.boot); px(c, 7, 14, 5, 2, C.boot) }
    else if (pose === 'walk2') { px(c, 3, 13, 6, 2, C.blue); px(c, 2, 14, 4, 2, C.boot); px(c, 7, 14, 4, 2, C.boot) }
    else if (pose === 'jump') { px(c, 2, 12, 3, 3, C.blue); px(c, 7, 13, 3, 2, C.blue); px(c, 1, 14, 4, 2, C.boot); px(c, 7, 14, 4, 2, C.boot) }
    else { px(c, 2, 13, 3, 2, C.blue); px(c, 7, 13, 3, 2, C.blue); px(c, 1, 14, 4, 2, C.boot); px(c, 7, 14, 4, 2, C.boot) }
  }
  c.restore()
}

function drawGoomba(c: CanvasRenderingContext2D, x: number, y: number, frame: number, squish: number) {
  if (squish > 0) {
    px(c, x + 1, y + 12, 14, 4, C.gBody)
    px(c, x + 2, y + 11, 12, 2, C.gDark)
    return
  }
  const step = Math.floor(frame / 12) % 2
  px(c, x + 3, y + 1, 10, 2, C.gBody)
  px(c, x + 1, y + 3, 14, 7, C.gBody)
  px(c, x + 2, y + 10, 12, 2, C.gDark)
  // eyes
  px(c, x + 4, y + 5, 2, 3, C.white); px(c, x + 10, y + 5, 2, 3, C.white)
  px(c, x + 5, y + 7, 1, 1, C.dark); px(c, x + 10, y + 7, 1, 1, C.dark)
  // brows
  px(c, x + 3, y + 4, 3, 1, C.dark); px(c, x + 10, y + 4, 3, 1, C.dark)
  // feet
  if (step === 0) { px(c, x, y + 12, 6, 3, C.gFoot); px(c, x + 10, y + 13, 6, 2, C.gFoot) }
  else { px(c, x, y + 13, 6, 2, C.gFoot); px(c, x + 10, y + 12, 6, 3, C.gFoot) }
}

function drawMushroom(c: CanvasRenderingContext2D, x: number, y: number) {
  px(c, x + 2, y + 1, 12, 6, C.red)
  px(c, x + 1, y + 3, 14, 4, C.red)
  px(c, x + 3, y + 2, 3, 2, C.white); px(c, x + 10, y + 2, 3, 2, C.white)
  px(c, x + 6, y + 4, 4, 2, C.white)
  px(c, x + 4, y + 8, 8, 7, '#f8e0b0')
  px(c, x + 4, y + 13, 8, 1, '#c89860')
}

function drawCoin(c: CanvasRenderingContext2D, x: number, y: number, phase: number) {
  const widths = [10, 6, 2, 6]
  const w = widths[phase % 4]
  const cx = x + 8
  px(c, cx - w / 2, y + 2, w, 12, C.gold)
  if (w > 4) {
    px(c, cx - w / 2 + 2, y + 4, w - 4, 8, C.goldIn)
    px(c, cx - w / 2, y + 4, 1, 8, C.white)
  }
}

function drawTile(c: CanvasRenderingContext2D, ch: string, x: number, y: number, tx: number, ty: number, fontReady: boolean) {
  switch (ch) {
    case '#': {
      px(c, x, y, 16, 16, C.ground)
      px(c, x, y, 16, 2, C.groundHi)
      px(c, x, y + 15, 16, 1, C.groundLo)
      px(c, x + 15, y, 1, 16, C.groundLo)
      const s = (tx * 7 + ty * 13) % 5
      px(c, x + 2 + s, y + 5, 2, 2, C.groundLo)
      px(c, x + 9 - s, y + 10, 2, 2, C.groundLo)
      px(c, x + 5, y + 12, 1, 1, C.groundLo)
      break
    }
    case 'B': {
      px(c, x, y, 16, 16, C.brick)
      px(c, x, y, 16, 1, C.brickHi)
      px(c, x, y + 7, 16, 1, C.dark)
      px(c, x + 7, y, 1, 7, C.dark)
      px(c, x + 3, y + 8, 1, 8, C.dark)
      px(c, x + 11, y + 8, 1, 8, C.dark)
      px(c, x, y + 15, 16, 1, C.dark)
      break
    }
    case 'Q': case 'M': {
      px(c, x, y, 16, 16, C.q)
      px(c, x, y, 16, 1, '#ffd070')
      px(c, x, y + 15, 16, 1, C.qDark)
      px(c, x + 15, y, 1, 16, C.qDark)
      px(c, x + 2, y + 2, 2, 2, C.qDark); px(c, x + 12, y + 2, 2, 2, C.qDark)
      px(c, x + 2, y + 12, 2, 2, C.qDark); px(c, x + 12, y + 12, 2, 2, C.qDark)
      if (fontReady) {
        c.fillStyle = '#fff'
        c.font = '8px "Press Start 2P"'
        c.textAlign = 'center'; c.textBaseline = 'top'
        c.fillText('?', x + 8, y + 5)
      }
      break
    }
    case 'U': {
      px(c, x, y, 16, 16, '#a06018')
      px(c, x, y, 16, 1, '#c88838')
      px(c, x, y + 15, 16, 1, '#5c3410')
      px(c, x + 15, y, 1, 16, '#5c3410')
      px(c, x + 2, y + 2, 2, 2, '#5c3410'); px(c, x + 12, y + 2, 2, 2, '#5c3410')
      px(c, x + 2, y + 12, 2, 2, '#5c3410'); px(c, x + 12, y + 12, 2, 2, '#5c3410')
      break
    }
    case 'X': {
      px(c, x, y, 16, 16, C.stone)
      px(c, x, y, 16, 2, C.stoneHi); px(c, x, y, 2, 16, C.stoneHi)
      px(c, x, y + 14, 16, 2, C.stoneLo); px(c, x + 14, y, 2, 16, C.stoneLo)
      break
    }
    case 'p': {
      px(c, x, y, 16, 16, C.pipe)
      if (tx % 2 === 0) { px(c, x, y, 2, 16, C.pipeLo); px(c, x + 3, y, 2, 16, C.pipeHi) }
      else { px(c, x + 14, y, 2, 16, C.pipeLo); px(c, x + 9, y, 2, 16, C.pipeHi) }
      px(c, x, y + 15, 16, 1, C.pipeLo)
      break
    }
    case 'I': {
      if (tx % 2 === 0) { px(c, x + 2, y, 14, 16, C.pipe); px(c, x + 4, y, 2, 16, C.pipeHi); px(c, x + 2, y, 1, 16, C.pipeLo) }
      else { px(c, x, y, 14, 16, C.pipe); px(c, x + 10, y, 2, 16, C.pipeHi); px(c, x + 13, y, 1, 16, C.pipeLo) }
      break
    }
    case 'F': {
      px(c, x + 7, y, 2, 16, C.pole)
      px(c, x + 7, y, 1, 16, C.white)
      break
    }
    case 'T': {
      px(c, x + 5, y + 8, 6, 6, C.pipe); px(c, x + 6, y + 9, 4, 4, C.pipeHi)
      px(c, x + 7, y + 14, 2, 2, C.pole)
      break
    }
    default: break
  }
}

function drawFlagCloth(c: CanvasRenderingContext2D, poleX: number, clothY: number) {
  const x = poleX * 16
  for (let i = 0; i < 5; i++) {
    const w = 14 - i * 2
    px(c, x + 9 - w, clothY + i * 2, w, 2, i < 2 ? '#30a020' : '#28881a')
  }
}

/* ============================== COMPONENT ============================== */

type Input = {
  l: boolean; r: boolean; run: boolean; jump: boolean
  jumpEdge: boolean; startEdge: boolean
}

export function MarioGame({ autoStart = false }: { autoStart?: boolean }) {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const stageRef = useRef<HTMLDivElement>(null)
  const inp = useRef<Input>({ l: false, r: false, run: false, jump: false, jumpEdge: false, startEdge: false })
  const stateRef = useRef<State>('title')
  const api = useRef<{ pause: () => void; mute: () => void; fs: () => void }>({ pause() {}, mute() {}, fs() {} })
  const fsBtnRef = useRef<HTMLButtonElement>(null)
  const [mutedUI, setMutedUI] = useState(false)

  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx0 = canvas.getContext('2d')
    if (!ctx0) return
    const ctx: CanvasRenderingContext2D = ctx0
    ctx.imageSmoothingEnabled = false
    void document.fonts?.load('8px "Press Start 2P"')

    /* ---------- game state (effect-local, rendered on canvas) ---------- */
    let state: State = 'title'
    let stateT = 0
    let frameN = 0
    let levelIdx = 0
    let score = 0
    let coinCount = 0
    let lives = 3
    let time = 300
    let timeT = 0
    let camX = 0
    let freeze = 0
    let grew = true
    let grabRow = 12
    let bonus = 0
    let musicStep = 0
    let fontReady = false
    void document.fonts?.ready.then(() => { fontReady = true })

    let L: Level = build(0)
    let player: Player = freshPlayer(false)
    let enemies: Enemy[] = []
    let items: Item[] = []
    let pops: Pop[] = []
    let parts: Part[] = []
    let bumps: Bump[] = []
    let flagClothY = 3 * TILE

    function freshPlayer(big: boolean): Player {
      const h = big ? 28 : 16
      return { x: 32, y: 13 * TILE - h, w: 12, h, vx: 0, vy: 0, face: 1, onG: false, coyote: 0, buf: 0, anim: 0, inv: 0, big }
    }

    function loadHi(): number {
      try { return Number(localStorage.getItem('ka-super-archive-bros-hi')) || 0 } catch { return 0 }
    }
    function saveHi(v: number) {
      try {
        const prev = loadHi()
        if (v > prev) localStorage.setItem('ka-super-archive-bros-hi', String(v))
      } catch { /* private mode */ }
    }
    let hi = loadHi()

    /* spawn voice — "JAI HIND!" plays on game start and on every respawn */
    let spawnSnd: HTMLAudioElement | null = null
    try {
      spawnSnd = new Audio('/sounds/JAI_HIND.mp3')
      spawnSnd.preload = 'auto'
      spawnSnd.volume = 1
    } catch { spawnSnd = null }
    function playSpawn() {
      if (!spawnSnd || mutedFlag) return
      try {
        spawnSnd.currentTime = 0
        void spawnSnd.play().catch(() => { /* autoplay guard */ })
      } catch { /* ignore */ }
    }

    function loadLevel() {
      L = build(levelIdx)
      enemies = L.spawns.map(s => ({ x: s.tx * TILE, y: s.ty * TILE, w: 16, h: 16, vx: 0, vy: 0, dir: -1, squish: 0 }))
      items = []; pops = []; parts = []; bumps = []
      player = freshPlayer(false)
      time = 300; timeT = 0; camX = 0
      flagClothY = 3 * TILE
      state = 'intro'; stateT = 0
      stateRef.current = state
      musicStep = 0
    }
    function startGame() {
      score = 0; coinCount = 0; lives = 3; levelIdx = 0
      loadLevel()
      playSpawn()
    }
    function respawn() {
      L = build(levelIdx)
      enemies = L.spawns.map(s => ({ x: s.tx * TILE, y: s.ty * TILE, w: 16, h: 16, vx: 0, vy: 0, dir: -1, squish: 0 }))
      items = []; pops = []; parts = []; bumps = []
      player = freshPlayer(false)
      time = 300; timeT = 0; camX = 0
      flagClothY = 3 * TILE
      state = 'intro'; stateT = 0
      stateRef.current = state
      playSpawn()
    }
    function die() {
      state = 'dying'; stateT = 0
      stateRef.current = state
      player.vy = -7.5
      sfx('die')
    }

    /* ---------- tile helpers ---------- */
    function tileAt(cx: number, cy: number): string {
      if (cx < 0 || cx >= L.w) return '#' // level edges are walls
      if (cy < 0) return '.'
      if (cy >= ROWS) return '.'
      return L.grid[cy][cx]
    }
    function solid(cx: number, cy: number): boolean {
      const ch = tileAt(cx, cy)
      return ch === '#' || ch === 'B' || ch === 'Q' || ch === 'M' || ch === 'U' || ch === 'X' || ch === 'p' || ch === 'I'
    }

    type Hit = { wall: boolean; landed: boolean; head: { cx: number; cy: number } | null }

    function move(e: Box): Hit {
      const hit: Hit = { wall: false, landed: false, head: null }
      // horizontal
      e.x += e.vx
      {
        const r0 = Math.max(0, Math.floor(e.y / TILE))
        const r1 = Math.min(ROWS - 1, Math.floor((e.y + e.h - 1) / TILE))
        if (e.vx > 0) {
          const cRight = Math.floor((e.x + e.w - 1) / TILE)
          for (let r = r0; r <= r1; r++) if (solid(cRight, r)) { e.x = cRight * TILE - e.w; e.vx = 0; hit.wall = true; break }
        } else if (e.vx < 0) {
          const cLeft = Math.floor(e.x / TILE)
          for (let r = r0; r <= r1; r++) if (solid(cLeft, r)) { e.x = (cLeft + 1) * TILE; e.vx = 0; hit.wall = true; break }
        }
      }
      // vertical
      e.y += e.vy
      {
        const c0 = Math.max(0, Math.floor(e.x / TILE))
        const c1 = Math.min(L.w - 1, Math.floor((e.x + e.w - 1) / TILE))
        if (e.vy > 0) {
          const rBot = Math.floor((e.y + e.h - 1) / TILE)
          for (let cc = c0; cc <= c1; cc++) if (solid(cc, rBot)) { e.y = rBot * TILE - e.h; e.vy = 0; hit.landed = true; break }
        } else if (e.vy < 0) {
          const rTop = Math.floor(e.y / TILE)
          let best: { cx: number; cy: number } | null = null
          let bestD = 1e9
          const center = e.x + e.w / 2
          for (let cc = c0; cc <= c1; cc++) {
            if (solid(cc, rTop)) {
              const d = Math.abs((cc + 0.5) * TILE - center)
              if (d < bestD) { bestD = d; best = { cx: cc, cy: rTop } }
            }
          }
          if (best) { e.y = (best.cy + 1) * TILE; e.vy = 0; hit.head = best }
        }
      }
      return hit
    }

    /* ---------- block interactions ---------- */
    function bumpTile(cx: number, cy: number) {
      const ch = tileAt(cx, cy)
      bumps.push({ cx, cy, t: 0 })
      if (ch === 'Q') {
        L.grid[cy][cx] = 'U'
        coinCount++; score += 200
        if (coinCount >= 100) { coinCount -= 100; lives++; sfx('oneup') } else sfx('coin')
        pops.push({ x: cx * TILE + 3, y: cy * TILE - 14, vy: -5, t: 0 })
      } else if (ch === 'M') {
        L.grid[cy][cx] = 'U'
        items.push({ x: cx * TILE, y: cy * TILE, w: 16, h: 16, vx: 0, vy: 0, rise: 48, dir: 1 })
        sfx('power')
      } else if (ch === 'B') {
        if (player.big) {
          L.grid[cy][cx] = '.'
          score += 50
          for (let i = 0; i < 4; i++) {
            parts.push({ x: cx * TILE + 4 + (i % 2) * 8, y: cy * TILE + 4 + Math.floor(i / 2) * 8, vx: (i % 2 === 0 ? -1.4 : 1.4), vy: -3 - Math.floor(i / 2), t: 0 })
          }
          sfx('break')
        } else sfx('bump')
      } else if (ch === '#' || ch === 'X' || ch === 'p' || ch === 'I' || ch === 'U') {
        sfx('bump')
      }
    }

    /* ---------- update ---------- */
    function update() {
      const inpV = inp.current
      const jumpEdge = inpV.jumpEdge
      const startEdge = inpV.startEdge
      inpV.jumpEdge = false
      inpV.startEdge = false

      if (state === 'title') {
        if (startEdge || jumpEdge) { ensureAudio(); startGame() }
        return
      }
      if (state === 'intro') {
        stateT++
        if (stateT > 90 || startEdge) { state = 'playing'; stateRef.current = state }
        return
      }
      if (state === 'pause') {
        if (startEdge) { state = 'playing'; stateRef.current = state; sfx('pause') }
        return
      }
      if (state === 'gameover' || state === 'win') {
        stateT++
        if (stateT > 40 && startEdge) { saveHi(score); hi = loadHi(); state = 'title'; stateT = 0; stateRef.current = state }
        return
      }
      if (state === 'clear') {
        stateT++
        if (stateT > 150) {
          levelIdx++
          if (levelIdx >= LEVEL_COUNT) { saveHi(score); hi = loadHi(); state = 'win'; stateT = 0; stateRef.current = state }
          else loadLevel()
        }
        return
      }
      if (freeze > 0) { freeze--; return }

      if (state === 'dying') {
        player.vy += 0.4
        player.y += player.vy
        stateT++
        if (stateT > 110) {
          lives--
          if (lives < 0) { saveHi(score); hi = loadHi(); state = 'gameover'; stateT = 0; stateRef.current = state }
          else respawn()
        }
        return
      }
      if (state === 'flag') {
        player.y += 2.2
        flagClothY = Math.min(flagClothY + 2.2, 11 * TILE)
        if (player.y >= 13 * TILE - player.h) {
          player.y = 13 * TILE - player.h
          state = 'walkoff'; stateT = 0; stateRef.current = state
          player.face = 1
        }
        return
      }
      if (state === 'walkoff') {
        stateT++
        player.vx = 1.3
        player.x += player.vx
        player.y = 13 * TILE - player.h
        if (stateT > 80 || player.x >= (L.flagX + 8) * TILE) {
          state = 'clear'; stateT = 0; stateRef.current = state
          bonus = 400 + Math.max(0, 12 - grabRow) * 200
          score += bonus
        }
        return
      }

      /* ----- playing ----- */
      if (startEdge) { state = 'pause'; stateRef.current = state; sfx('pause'); return }

      timeT++
      if (timeT >= 24) {
        timeT = 0; time--
        if (time <= 0) { die(); return }
      }

      // player physics
      const acc = inpV.run ? 0.18 : 0.12
      const max = inpV.run ? 2.5 : 1.5
      if (inpV.l) { player.vx -= player.vx > 0 ? 0.3 : acc; player.face = -1 }
      else if (inpV.r) { player.vx += player.vx < 0 ? 0.3 : acc; player.face = 1 }
      else if (player.onG) { player.vx *= 0.85; if (Math.abs(player.vx) < 0.08) player.vx = 0 }
      if (Math.abs(player.vx) > max) player.vx *= 0.97

      if (player.onG) player.coyote = 6
      else if (player.coyote > 0) player.coyote--
      if (jumpEdge) player.buf = 6
      else if (player.buf > 0) player.buf--
      if (player.buf > 0 && player.coyote > 0) {
        player.vy = -6.5
        player.onG = false
        player.coyote = 0; player.buf = 0
        sfx('jump')
      }
      player.vy += (player.vy < 0 && inpV.jump) ? 0.24 : 0.52
      if (player.vy > 7.5) player.vy = 7.5

      const hit = move(player)
      if (hit.wall) player.vx = 0
      if (hit.landed) player.onG = true
      else if (player.vy !== 0) player.onG = false
      if (hit.head) bumpTile(hit.head.cx, hit.head.cy)

      // camera edge: never walk off the left of the screen
      if (player.x < camX + 2) { player.x = camX + 2; if (player.vx < 0) player.vx = 0 }

      player.anim++
      if (player.inv > 0) player.inv--

      // coin tiles
      {
        const c0 = Math.max(0, Math.floor(player.x / TILE))
        const c1 = Math.min(L.w - 1, Math.floor((player.x + player.w - 1) / TILE))
        const r0 = Math.max(0, Math.floor(player.y / TILE))
        const r1 = Math.min(ROWS - 1, Math.floor((player.y + player.h - 1) / TILE))
        for (let r = r0; r <= r1; r++) {
          for (let c2 = c0; c2 <= c1; c2++) {
            if (tileAt(c2, r) === 'o') {
              L.grid[r][c2] = '.'
              coinCount++; score += 200
              if (coinCount >= 100) { coinCount -= 100; lives++; sfx('oneup') } else sfx('coin')
            }
          }
        }
      }

      // enemies
      for (const en of enemies) {
        if (en.squish > 0) { en.squish--; continue }
        en.vx = 0.35 * en.dir
        en.vy = Math.min(en.vy + 0.4, 7)
        const eh = move(en)
        if (eh.wall) en.dir = (en.dir === 1 ? -1 : 1)
        if (en.y > VH + 40) en.squish = 1 // fell into pit: remove silently
        // touch player?
        if (state !== 'playing') continue
        if (player.x < en.x + en.w && player.x + player.w > en.x &&
            player.y < en.y + en.h && player.y + player.h > en.y) {
          const stomp = player.vy > 0 && (player.y + player.h) - en.y < 10
          if (stomp) {
            en.squish = 30
            score += 100
            player.vy = inpV.jump ? -6.5 : -4.5
            player.y = en.y - player.h
            sfx('stomp')
          } else if (player.inv <= 0) {
            if (player.big) {
              player.big = false; player.h = 16; player.y += 12
              player.inv = 120; freeze = 40; grew = false
              sfx('shrink')
            } else { die(); return }
          }
        }
      }
      enemies = enemies.filter(e => e.squish !== 1)

      // items (mushrooms)
      for (const it of items) {
        if (it.rise > 0) { it.rise--; it.y -= TILE / 48; continue }
        it.vy = Math.min(it.vy + 0.4, 7)
        it.vx = 0.6 * it.dir
        const ih = move(it)
        if (ih.wall) it.dir = (it.dir === 1 ? -1 : 1)
        if (it.y > VH + 40) it.rise = -1
        if (state === 'playing' &&
            player.x < it.x + it.w && player.x + player.w > it.x &&
            player.y < it.y + it.h && player.y + player.h > it.y) {
          it.rise = -1
          score += 1000
          sfx('power')
          if (!player.big) { player.big = true; player.h = 28; player.y -= 12; freeze = 45; grew = true }
        }
      }
      items = items.filter(it => it.rise >= 0)

      // coin pops + particles + bumps
      for (const p of pops) { p.vy += 0.4; p.y += p.vy; p.t++ }
      pops = pops.filter(p => p.t < 34)
      for (const p of parts) { p.vy += 0.35; p.x += p.vx; p.y += p.vy; p.t++ }
      parts = parts.filter(p => p.t < 60)
      for (const b of bumps) b.t++
      bumps = bumps.filter(b => b.t < 12)

      // flag
      if (player.x + player.w >= L.flagX * TILE + 6) {
        grabRow = Math.floor(player.y / TILE)
        state = 'flag'; stateT = 0; stateRef.current = state
        player.x = L.flagX * TILE - 11
        player.vx = 0; player.vy = 0
        sfx('flag')
        return
      }

      // pit
      if (player.y > VH + 24) { die(); return }

      // camera (monotonic, classic no-backtrack)
      camX = Math.max(camX, Math.min(Math.max(player.x - 112, 0), L.w * TILE - VW))

      // music sequencer
      if (frameN % 8 === 0) {
        const ln = LEAD[musicStep % LEAD.length]
        if (ln) tone(midi(ln), midi(ln), 0.11, 'square', 0.045)
        if (musicStep % 2 === 0) {
          const bn = BASS[(musicStep / 2) % BASS.length]
          if (bn) tone(midi(bn), midi(bn), 0.16, 'triangle', 0.07)
        }
        musicStep++
      }
    }

    /* ---------- render ---------- */
    function txt(s: string, x: number, y: number, color = '#fff', size = 8, align: CanvasTextAlign = 'left') {
      if (!fontReady) return
      ctx.font = `${size}px "Press Start 2P"`
      ctx.textAlign = align
      ctx.textBaseline = 'top'
      ctx.fillStyle = '#000'
      ctx.fillText(s, x + 1, y + 1)
      ctx.fillStyle = color
      ctx.fillText(s, x, y)
    }
    const pad = (n: number, len: number) => String(Math.max(0, Math.floor(n))).padStart(len, '0')

    function skyColor(): string {
      if (L.theme === 'day') return '#5c94fc'
      if (L.theme === 'dusk') return '#7a4ea8'
      return '#0a0a1e'
    }

    function drawDecor() {
      if (L.theme === 'night' || L.theme === 'dusk') {
        ctx.fillStyle = L.theme === 'night' ? '#f8f8f8' : '#e8d8f8'
        for (const st of L.stars) {
          const sx = st.x - camX * 0.4
          if (sx < -4 || sx > VW + 4) continue
          ctx.fillRect(Math.round(sx), st.y, 2, 2)
        }
      }
      if (L.theme === 'day' || L.theme === 'dusk') {
        for (const cl of L.clouds) {
          const cx = cl.x - camX * 0.6
          if (cx < -40 || cx > VW + 40) continue
          px(ctx, cx, cl.y + 4, 30, 8, '#f8f8f8')
          px(ctx, cx + 6, cl.y, 16, 8, '#f8f8f8')
          px(ctx, cx + 2, cl.y + 10, 26, 2, '#d8e8f8')
        }
        for (const hx of L.hills) {
          const hxx = hx * 16 - camX
          if (hxx < -80 || hxx > VW + 80) continue
          px(ctx, hxx, 13 * TILE - 6, 64, 6, '#28881a')
          px(ctx, hxx + 12, 13 * TILE - 14, 40, 8, '#28881a')
          px(ctx, hxx + 22, 13 * TILE - 20, 20, 6, '#28881a')
        }
      }
    }

    function poseFor(): 'stand' | 'walk1' | 'walk2' | 'jump' {
      if (state === 'dying') return 'jump'
      if (!player.onG && state === 'playing') return 'jump'
      if (state === 'flag') return 'jump'
      if (Math.abs(player.vx) > 0.2 || (state === 'walkoff')) {
        return Math.floor(player.anim / 6) % 2 === 0 ? 'walk1' : 'walk2'
      }
      return 'stand'
    }

    function render() {
      ctx.setTransform(SCALE, 0, 0, SCALE, 0, 0)
      px(ctx, 0, 0, VW, VH, state === 'title' || state === 'intro' || state === 'gameover' || state === 'win' ? '#000' : skyColor())

      if (state === 'title') { renderTitle(); return }
      if (state === 'intro') { renderIntro(); return }
      if (state === 'gameover') { renderGameOver(); return }
      if (state === 'win') { renderWin(); return }

      drawDecor()

      ctx.save()
      ctx.translate(-Math.round(camX), 0)

      // rising mushrooms render behind blocks
      for (const it of items) if (it.rise > 0) drawMushroom(ctx, it.x, it.y)

      // tiles
      const c0 = Math.max(0, Math.floor(camX / TILE) - 1)
      const c1 = Math.min(L.w - 1, c0 + 18)
      for (let r = 0; r < ROWS; r++) {
        for (let cc = c0; cc <= c1; cc++) {
          const ch = L.grid[r][cc]
          if (ch === '.') continue
          let off = 0
          const bump = bumps.find(b => b.cx === cc && b.cy === r)
          if (bump) off = -Math.round(4 * Math.sin(Math.PI * bump.t / 12))
          if (ch === 'o') drawCoin(ctx, cc * TILE, r * TILE, Math.floor(frameN / 8))
          else drawTile(ctx, ch, cc * TILE, r * TILE + off, cc, r, fontReady)
        }
      }
      drawFlagCloth(ctx, L.flagX, flagClothY)

      // coin pops
      for (const p of pops) drawCoin(ctx, p.x, p.y, Math.floor(p.t / 4))

      // particles
      for (const p of parts) px(ctx, p.x, p.y, 5, 5, C.brick)

      // free items
      for (const it of items) if (it.rise <= 0) drawMushroom(ctx, it.x, it.y)

      // enemies
      for (const en of enemies) drawGoomba(ctx, en.x, en.y, frameN, en.squish)

      // player (invulnerability flicker)
      const flicker = player.inv > 0 && Math.floor(frameN / 4) % 2 === 0
      const growFlicker = freeze > 0 && Math.floor(frameN / 4) % 2 === 0
      const showBig = growFlicker ? !grew : player.big
      if (!flicker) drawHero(ctx, player.x, player.y + player.h - (showBig ? 28 : 16), showBig, player.face, poseFor())

      ctx.restore()

      // HUD
      txt('HERO', 8, 8); txt(pad(score, 6), 8, 18)
      drawCoin(ctx, 70, 14, 0)
      txt('×' + pad(coinCount, 2), 86, 18)
      txt('WORLD', 122, 8); txt(L.name, 130, 18)
      txt('TIME', 190, 8)
      txt(pad(time, 3), 194, 18, time < 100 ? '#f8b800' : '#fff')

      if (state === 'pause') {
        ctx.fillStyle = 'rgba(0,0,0,0.6)'
        ctx.fillRect(0, 0, VW, VH)
        txt('PAUSED', VW / 2, 104, '#fff', 12, 'center')
        txt('ENTER RESUMES', VW / 2, 132, '#c8c8c8', 8, 'center')
      }
      if (state === 'clear') {
        ctx.fillStyle = 'rgba(0,0,0,0.55)'
        ctx.fillRect(0, 0, VW, VH)
        txt('COURSE CLEAR!', VW / 2, 96, '#fff', 12, 'center')
        txt('BONUS ' + pad(bonus, 4), VW / 2, 124, '#f8b800', 8, 'center')
      }
    }

    function renderTitle() {
      // logo box
      ctx.strokeStyle = '#fff'; ctx.lineWidth = 2
      ctx.strokeRect(44, 34, 168, 74)
      px(ctx, 46, 36, 164, 70, '#8c2400')
      txt('SUPER', VW / 2, 46, '#f8d878', 16, 'center')
      txt('ARCHIVE BROS.', VW / 2, 72, '#fff', 8, 'center')
      txt('TOP ' + pad(hi, 6), VW / 2, 122, '#c8c8c8', 8, 'center')
      if (Math.floor(frameN / 30) % 2 === 0) txt('PRESS ENTER OR TAP A', VW / 2, 146, '#fff', 8, 'center')
      txt('ARROWS MOVE   Z JUMP   X RUN', VW / 2, 172, '#909090', 8, 'center')
      txt('ENTER PAUSE   M SOUND', VW / 2, 186, '#909090', 8, 'center')
      drawHero(ctx, 96, 202, false, 1, 'walk1')
      drawGoomba(ctx, 148, 202, frameN, 0)
    }
    function renderIntro() {
      txt('WORLD ' + L.name, VW / 2, 88, '#fff', 10, 'center')
      drawHero(ctx, 106, 110, false, 1, 'stand')
      txt('× ' + lives, 130, 114, '#fff', 8, 'center')
      txt(L.theme === 'night' ? 'GOOD LUCK.' : 'GET READY.', VW / 2, 150, '#909090', 8, 'center')
    }
    function renderGameOver() {
      txt('GAME OVER', VW / 2, 92, '#fff', 12, 'center')
      txt('SCORE ' + pad(score, 6), VW / 2, 122, '#c8c8c8', 8, 'center')
      if (stateT > 40 && Math.floor(frameN / 30) % 2 === 0) txt('PRESS ENTER', VW / 2, 156, '#fff', 8, 'center')
    }
    function renderWin() {
      txt('ALL COURSES CLEARED!', VW / 2, 80, '#f8d878', 10, 'center')
      txt('FINAL SCORE', VW / 2, 112, '#c8c8c8', 8, 'center')
      txt(pad(score, 6), VW / 2, 126, '#fff', 10, 'center')
      txt('THE ARCHIVE SALUTES YOU', VW / 2, 156, '#fff', 8, 'center')
      if (stateT > 40 && Math.floor(frameN / 30) % 2 === 0) txt('PRESS ENTER', VW / 2, 184, '#c8c8c8', 8, 'center')
    }

    /* ---------- loop ---------- */
    let last = performance.now()
    let acc = 0
    let raf = 0
    function loop(now: number) {
      raf = requestAnimationFrame(loop)
      let dt = now - last
      last = now
      if (dt > 100) dt = 100
      acc += dt
      while (acc >= STEP) { update(); frameN++; acc -= STEP }
      render()
    }
    raf = requestAnimationFrame(loop)

    /* one-click boot — the launcher click carries user activation, so audio
       starts cleanly; the PRESS ENTER title screen is skipped entirely */
    if (autoStart) { ensureAudio(); startGame() }

    /* ---------- input ---------- */
    const GAMEKEYS = new Set(['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', ' '])
    function onKey(e: KeyboardEvent) {
      const t = e.target as HTMLElement | null
      if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA')) return
      const k = e.key
      if (GAMEKEYS.has(k) && stateRef.current !== 'title') e.preventDefault()
      switch (k) {
        case 'ArrowLeft': case 'a': case 'A': inp.current.l = true; break
        case 'ArrowRight': case 'd': case 'D': inp.current.r = true; break
        case 'Shift': case 'x': case 'X': inp.current.run = true; break
        case ' ': case 'ArrowUp': case 'w': case 'W': case 'z': case 'Z':
          if (!e.repeat) inp.current.jumpEdge = true
          inp.current.jump = true
          break
        case 'Enter':
          if (!e.repeat) inp.current.startEdge = true
          break
        case 'm': case 'M':
          if (!e.repeat) { mutedFlag = !mutedFlag; setMutedUI(mutedFlag) }
          break
        default: break
      }
    }
    function onKeyUp(e: KeyboardEvent) {
      const k = e.key
      switch (k) {
        case 'ArrowLeft': case 'a': case 'A': inp.current.l = false; break
        case 'ArrowRight': case 'd': case 'D': inp.current.r = false; break
        case 'Shift': case 'x': case 'X': inp.current.run = false; break
        case ' ': case 'ArrowUp': case 'w': case 'W': case 'z': case 'Z': inp.current.jump = false; break
        default: break
      }
    }
    function autoPause() {
      if (stateRef.current === 'playing') { state = 'pause'; stateRef.current = state }
      inp.current.l = false; inp.current.r = false; inp.current.jump = false; inp.current.run = false
    }
    function onBlur() { autoPause() }
    function onVis() { if (document.hidden) autoPause() }
    window.addEventListener('keydown', onKey)
    window.addEventListener('keyup', onKeyUp)
    window.addEventListener('blur', onBlur)
    document.addEventListener('visibilitychange', onVis)

    api.current.pause = () => {
      if (stateRef.current === 'playing') { state = 'pause'; stateRef.current = state; sfx('pause') }
      else if (stateRef.current === 'pause') { state = 'playing'; stateRef.current = state; sfx('pause') }
    }
    api.current.mute = () => { mutedFlag = !mutedFlag; setMutedUI(mutedFlag) }
    api.current.fs = () => {
      const el = stageRef.current
      if (!el || !document.fullscreenEnabled) return
      if (document.fullscreenElement) void document.exitFullscreen()
      else void el.requestFullscreen().catch(() => {})
    }

    return () => {
      cancelAnimationFrame(raf)
      window.removeEventListener('keydown', onKey)
      window.removeEventListener('keyup', onKeyUp)
      window.removeEventListener('blur', onBlur)
      document.removeEventListener('visibilitychange', onVis)
      api.current = { pause() {}, mute() {}, fs() {} }
    }
  }, [autoStart])

  // hide the fullscreen button where element fullscreen is unsupported
  // (iOS Safari) — a DOM sync, no state needed
  useEffect(() => {
    const btn = fsBtnRef.current
    if (btn && !document.fullscreenEnabled) btn.hidden = true
  }, [])

  /* ---------- touch pads ---------- */
  const padDown = (key: 'l' | 'r' | 'run' | 'jump') => (e: React.PointerEvent<HTMLButtonElement>) => {
    e.preventDefault()
    ensureAudio()
    inp.current[key] = true
    if (key === 'jump') {
      inp.current.jumpEdge = true
      if (stateRef.current === 'title') inp.current.startEdge = true
    }
  }
  const padUp = (key: 'l' | 'r' | 'run' | 'jump') => (e: React.PointerEvent<HTMLButtonElement>) => {
    e.preventDefault()
    inp.current[key] = false
  }

  return (
    <div className="game-stage" ref={stageRef}>
      <div className="game-frame">
        <canvas
          ref={canvasRef}
          width={VW * SCALE}
          height={VH * SCALE}
          className="game-canvas"
          onContextMenu={e => e.preventDefault()}
          onPointerDown={() => {
            ensureAudio()
            const s = stateRef.current
            if (s === 'title' || s === 'gameover' || s === 'win') inp.current.startEdge = true
          }}
        />
        <div className="game-crt" aria-hidden="true" />
      </div>
      <div className="game-ui">
        <button type="button" className="game-btn" onClick={e => { api.current.pause(); e.currentTarget.blur() }}>
          ⏸ PAUSE
        </button>
        {(
          <button ref={fsBtnRef} type="button" className="game-btn" onClick={e => { api.current.fs(); e.currentTarget.blur() }}>
            ⤢ FULLSCREEN
          </button>
        )}
        <button type="button" className="game-btn" onClick={e => { api.current.mute(); e.currentTarget.blur() }}>
          {mutedUI ? '♪ SOUND OFF' : '♪ SOUND ON'}
        </button>
      </div>
      <div className="game-pads">
        <div className="game-pad-group">
          <button type="button" className="game-pad" onPointerDown={padDown('l')} onPointerUp={padUp('l')} onPointerCancel={padUp('l')} onPointerLeave={padUp('l')} onContextMenu={e => e.preventDefault()}>◀</button>
          <button type="button" className="game-pad" onPointerDown={padDown('r')} onPointerUp={padUp('r')} onPointerCancel={padUp('r')} onPointerLeave={padUp('r')} onContextMenu={e => e.preventDefault()}>▶</button>
        </div>
        <div className="game-pad-group">
          <button type="button" className="game-pad" onPointerDown={padDown('run')} onPointerUp={padUp('run')} onPointerCancel={padUp('run')} onPointerLeave={padUp('run')} onContextMenu={e => e.preventDefault()}>B</button>
          <button type="button" className="game-pad" onPointerDown={padDown('jump')} onPointerUp={padUp('jump')} onPointerCancel={padUp('jump')} onPointerLeave={padUp('jump')} onContextMenu={e => e.preventDefault()}>A</button>
        </div>
      </div>
    </div>
  )
}
